import torch
from torch import Tensor, nn
import torch.nn.functional as F
from functools import partial


def make_conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def make_conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class ResUnit(nn.Module):
    expansion = 1

    def __init__(self, inplanes, planes, stride=1, skip: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv1 = make_conv3(inplanes, planes, stride)
        self.bn1 = norm_layer(planes)
        self.conv2 = make_conv3(planes, planes)
        self.bn2 = norm_layer(planes)
        self.relu1 = nn.Hardswish()
        self.relu2 = nn.Hardswish()
        self.skip = skip
        self.stride = stride

    def forward(self, input: Tensor) -> Tensor:
        shortcut_out = input

        y = self.conv1(input)
        y = self.bn1(y)
        y = self.relu1(y)
        y = self.conv2(y)
        y = self.bn2(y)

        if self.skip is not None:
            shortcut_out = self.skip(input)

        y += shortcut_out
        y = self.relu2(y)
        return y


class ConvBNActivation(nn.Sequential):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        layers = [
            nn.Conv2d(in_channels, out_channels, kernel_size, stride, padding, groups=groups, bias=False),
            nn.BatchNorm2d(out_channels),
        ]
        if act:
            layers.append(nn.Hardswish())
        super().__init__(*layers)


class BlockStage(nn.Module):
    def __init__(self, planes, n, stride, in_ch, norm_layer=None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        blocks = []
        downsample = None
        if stride != 1 or in_ch != planes * ResUnit.expansion:
            downsample = nn.Sequential(
                make_conv1(in_ch, planes * ResUnit.expansion, stride),
                norm_layer(planes * ResUnit.expansion),
            )
        blocks.append(ResUnit(in_ch, planes, stride, downsample))
        in_ch = planes * ResUnit.expansion
        for _ in range(1, n):
            blocks.append(ResUnit(in_ch, planes))
        self.blocks = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.blocks(x)


class Network(nn.Module):
    def __init__(self, stage_cfg, in_chans=3, num_classes=10, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None, output_stride=32, **kwargs):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-5)
        self.num_classes = num_classes
        self.stem = ConvBNActivation(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        stages = []
        for idx, (planes, n, stride) in enumerate(stage_cfg):
            stage = BlockStage(planes, n, stride, in_ch)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.ModuleList(stages)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, input):
        input = self.stem(input)
        for stage in self.stages:
            input = stage(input)
        return input

    def forward_head(self, input, pre_logits: bool = False):
        input = F.adaptive_avg_pool2d(input, 1)
        input = input.flatten(1)
        input = self.drop(input)
        return input if pre_logits else self.fc(input)

    def forward(self, input):
        input = self.forward_features(input)
        input = self.forward_head(input)
        return input


def _network(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": [(8, 1, 1), (16, 1, 2), (32, 2, 2), (64, 2, 2)], "base": [(8, 2, 1), (16, 2, 2), (32, 3, 2), (64, 3, 2)]}
    model = Network(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def build_model(weights=None, progress=True, **kwargs):
    return _network('base', weights, progress, **kwargs)


